content.css:
.clock-root {
  width: 100%;
  height: 100%;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  font-family: "Segoe UI", "Segoe UI Semibold", sans-serif;
  box-sizing: border-box;
  padding: 8px;
}
.clock-time {
  font-weight: 600;
  line-height: 1.1;
  white-space: nowrap;
}
.clock-date {
  font-weight: 400;
  opacity: 0.8;
  margin-top: 4px;
  white-space: nowrap;
}
